@st.cache_resource(show_spinner=False)
def _finance_prepare_bundle(payload, digest, namespace):
    data = base64.b64decode(payload)
    if hashlib.sha256(data).hexdigest() != digest:
        raise RuntimeError("The deployment file is incomplete. Upload the original finance_app.py again.")
    temporary_directory = tempfile.TemporaryDirectory(prefix="finance-apps-")
    root = Path(temporary_directory.name).resolve()
    with ZipFile(io.BytesIO(data)) as archive:
        for name in archive.namelist():
            if not (root / name).resolve().is_relative_to(root):
                raise RuntimeError("Invalid bundled file path.")
        archive.extractall(root)
    # A version-specific package avoids collisions with files from older uploads.
    spec = importlib.util.spec_from_file_location(
        namespace, root / "__init__.py", submodule_search_locations=[str(root)]
    )
    module = importlib.util.module_from_spec(spec)
    sys.modules[namespace] = module
    spec.loader.exec_module(module)
    # Retain the temporary directory for the lifetime of the cached resource.
    return temporary_directory


_finance_runtime = _finance_prepare_bundle(_BUNDLE_DATA, _BUNDLE_DIGEST, _BUNDLE_NAMESPACE)

"""Shared Streamlit entry point for the three finance file transformers."""

import streamlit as st


def arap() -> None:
    from _finance_bundle_069cabc54865081b.arap_file_transformer.app import main as run_app

    run_app()


def pool() -> None:
    from _finance_bundle_069cabc54865081b.invoice_pool_transformer.app import main as run_app

    run_app()


def accrual() -> None:
    from _finance_bundle_069cabc54865081b.accrual_file_transformer.app import main as run_app

    run_app()


def render_home(app_pages) -> None:
    st.title("Finance Apps")
    st.write("Choose the app you need to prepare your posting files.")
    descriptions = [
        "Select a posting month, generate company journals, and mark posted ARAP rows.",
        "Process AX or D365 invoice-pool workbooks and export rows marked yes.",
        "Transform an accrual workbook into separate AX and D365 posting files by company.",
    ]
    for column, page, description in zip(st.columns(3), app_pages, descriptions):
        with column:
            with st.container(border=True):
                st.subheader(page.title)
                st.write(description)
                st.page_link(page, label=f"Open {page.title}", use_container_width=True)
    st.info(
        "To work in several apps at once, open their navigation links in separate "
        "browser tabs. Each browser tab has its own uploads and inputs."
    )
    st.caption(
        "Switching apps within this tab can reset uploads and inputs. "
        "Keep a separate browser tab open for each app when you want to preserve your work."
    )


def main() -> None:
    st.set_page_config(page_title="Finance Apps", page_icon="📄", layout="wide")
    app_pages = [
        st.Page(arap, title="ARAP", url_path="arap"),
        st.Page(pool, title="Pool", url_path="pool"),
        st.Page(accrual, title="ACCRUAL", url_path="accrual"),
    ]

    def home() -> None:
        render_home(app_pages)

    page = st.navigation(
        [st.Page(home, title="Home", default=True), *app_pages],
        position="top",
    )
    page.run()


if __name__ == "__main__":
    main()
